// LeetCode 389: Find the Difference [Easy]
// https://leetcode.com/problems/find-the-difference/
//
// Benchmark: 500,000 iterations (2025-04-08)
//   My solution (char counting): avg 1.04us
//   AI solution (XOR):            avg 158ns
//   -> AI solution is 6.54x faster
//
// You are given two strings `s` and `t`. String `t` is generated by random
// shuffling string `s` and then adding one more letter at a random position.
//
// Return the letter that was added to `t`.
//
// Examples:
//   s = "abcd", t = "abcde" -> 'e'
//   s = "",     t = "y"     -> 'y'
//
// Constraints:
//   - 0 <= s.length <= 1000
//   - t.length == s.length + 1
//   - s and t consist of lowercase English letters
//
// Run:  cargo run --example lc_0389_find_the_difference
// Test: cargo test --example lc_0389_find_the_difference
// Bench: cargo test --example lc_0389_find_the_difference bench -- --nocapture

/// My solution module — character counting.
///
/// Count occurrences of each letter in `t`, then subtract counts from `s`.
/// The letter with remaining count 1 is the answer.
///
/// Time:  O(n) where n = s.len() + t.len()
/// Space: O(1) — fixed 26-element array
mod my_solution {
    pub struct Solution;

    impl Solution {
        /// Find the letter added to `t` that is not in `s`.
        ///
        /// # Arguments
        ///
        /// * `s` - Original string
        /// * `t` - Shuffled `s` with one extra letter
        ///
        /// # Returns
        ///
        /// The extra character
        pub fn find_the_difference(s: String, t: String) -> char {
            let mut counts = [0i32; 26];
            for b in t.bytes() {
                counts[(b - b'a') as usize] += 1;
            }
            for b in s.bytes() {
                counts[(b - b'a') as usize] -= 1;
            }
            // The only nonzero entry is the added letter
            let idx = counts
                .iter()
                .position(|&c| c != 0)
                .expect("there must be one added letter");
            (b'a' + idx as u8) as char
        }
    }
}

/// AI solution module — XOR approach.
///
/// XOR all bytes in `s` and `t` together. Since every character in `s`
/// appears in `t` (they cancel), the result is the added character.
/// This avoids even the 26-element counting array.
///
/// Time:  O(n)
/// Space: O(1) — single accumulator variable
mod ai_solution {
    pub struct Solution;

    impl Solution {
        /// Find the letter added to `t` that is not in `s`.
        ///
        /// # Arguments
        ///
        /// * `s` - Original string
        /// * `t` - Shuffled `s` with one extra letter
        ///
        /// # Returns
        ///
        /// The extra character
        pub fn find_the_difference(s: String, t: String) -> char {
            // XOR all bytes — duplicates cancel, leaving the added char
            let xor = s
                .bytes()
                .chain(t.bytes())
                .fold(0u8, |acc, b| acc ^ b);
            xor as char
        }
    }
}

fn main() {
    let cases = [
        ("abcd", "abcde", 'e'),
        ("", "y", 'y'),
    ];

    println!("--- My Solution ---");
    for (s, t, expected) in &cases {
        let result = my_solution::Solution::find_the_difference(
            s.to_string(),
            t.to_string(),
        );
        println!("  s={s:?}, t={t:?} -> '{result}' (expected '{expected}')");
    }

    println!("--- AI Solution ---");
    for (s, t, expected) in &cases {
        let result = ai_solution::Solution::find_the_difference(
            s.to_string(),
            t.to_string(),
        );
        println!("  s={s:?}, t={t:?} -> '{result}' (expected '{expected}')");
    }
}

#[cfg(test)]
mod tests {
    macro_rules! test_find_diff {
        ($mod_name:ident, $sol_path:path) => {
            mod $mod_name {
                use $sol_path as Solution;

                #[test]
                fn test_example1() {
                    assert_eq!(
                        Solution::find_the_difference(
                            "abcd".to_string(),
                            "abcde".to_string()
                        ),
                        'e'
                    );
                }

                #[test]
                fn test_example2() {
                    assert_eq!(
                        Solution::find_the_difference(
                            "".to_string(),
                            "y".to_string()
                        ),
                        'y'
                    );
                }

                #[test]
                fn test_duplicate_letters() {
                    assert_eq!(
                        Solution::find_the_difference(
                            "aab".to_string(),
                            "aaba".to_string()
                        ),
                        'a'
                    );
                }

                #[test]
                fn test_single_char() {
                    assert_eq!(
                        Solution::find_the_difference(
                            "a".to_string(),
                            "aa".to_string()
                        ),
                        'a'
                    );
                }

                #[test]
                fn test_added_at_front() {
                    assert_eq!(
                        Solution::find_the_difference(
                            "abc".to_string(),
                            "zabc".to_string()
                        ),
                        'z'
                    );
                }
            }
        };
    }

    test_find_diff!(my_tests, crate::my_solution::Solution);
    test_find_diff!(ai_tests, crate::ai_solution::Solution);

    #[test]
    fn bench_comparison() {
        use std::time::Instant;

        let iterations = 500_000_u32;
        let s: String = (0..1000).map(|i| (b'a' + (i % 26) as u8) as char).collect();
        let mut t = s.clone();
        t.push('x');

        let start = Instant::now();
        for _ in 0..iterations {
            std::hint::black_box(
                crate::my_solution::Solution::find_the_difference(
                    std::hint::black_box(s.clone()),
                    std::hint::black_box(t.clone()),
                ),
            );
        }
        let my_duration = start.elapsed();

        let start = Instant::now();
        for _ in 0..iterations {
            std::hint::black_box(
                crate::ai_solution::Solution::find_the_difference(
                    std::hint::black_box(s.clone()),
                    std::hint::black_box(t.clone()),
                ),
            );
        }
        let ai_duration = start.elapsed();

        println!("\n--- Benchmark ({iterations} iterations) ---");
        println!(
            "My solution:  {:.2?} (avg {:.2?})",
            my_duration,
            my_duration / iterations
        );
        println!(
            "AI solution:  {:.2?} (avg {:.2?})",
            ai_duration,
            ai_duration / iterations
        );
        let ratio = my_duration.as_secs_f64() / ai_duration.as_secs_f64();
        if ratio > 1.0 {
            println!("-> AI solution is {ratio:.2}x faster");
        } else {
            println!("-> My solution is {:.2}x faster", 1.0 / ratio);
        }
    }
}
